$probe = @'
import { spawn } from "node:child_process";
// Simulate exactly what dsh-mcp-gateway/lib/stdio.js:connect does with our server spec
const spec = { command: "D:\\nvm\\nodejs\\node.exe", args: ["C:/Users/Administrator/.dsh/profiles/web/node_modules/@openviking/dsh-memory-plugin/servers/mcp-proxy.mjs"] };
const child = spawn(spec.command, spec.args, { stdio:["pipe","pipe","pipe"], windowsHide:true, env: process.env });
let out="", err="";
child.stdout.on("data",d=>out+=d.toString());
child.stderr.on("data",d=>err+=d.toString());
child.on("error",e=>{console.log("SPAWN_ERROR "+e.message);process.exit(0)});
const R=o=>child.stdin.write(JSON.stringify(o)+"\n");
const results={};
let id=1; const ask=(method,params)=>{const i=id++;R({jsonrpc:"2.0",id:i,method,params});return i;};
const i1=ask("initialize",{protocolVersion:"2024-11-05",capabilities:{},clientInfo:{name:"dsh-mcp-gateway",version:"0.1.0"}});
setTimeout(()=>{R({jsonrpc:"2.0",method:"notifications/initialized"});ask("tools/list",{});},800);
setTimeout(()=>{
  const lines=out.split(/\r?\n/).filter(Boolean);
  let init=null, tools=null;
  for(const l of lines){try{const m=JSON.parse(l);if(m.id===1&&m.result)init=m.result;if(m.id===2&&m.result&&m.result.tools)tools=m.result.tools;}catch{}}
  console.log("HANDSHAKE="+(init?("OK serverInfo="+JSON.stringify(init.serverInfo)):"FAIL"));
  console.log("TOOLS_LIST="+(tools?("OK count="+tools.length+"; sample="+tools.slice(0,5).map(t=>t.name).join(",")):"FAIL"));
  // try a real tool call: health (cheap)
  if(tools){ R({jsonrpc:"2.0",id:99,method:"tools/call",params:{name:"health",arguments:{}}});
    setTimeout(()=>{ const l2=out.split(/\r?\n/).filter(Boolean); let call=null; for(const l of l2){try{const m=JSON.parse(l);if(m.id===99)call=m;}catch{}} console.log("CALL health="+(call?JSON.stringify(call.result??call.error).slice(0,160):"NO_RESPONSE")); if(err)console.log("STDERR_TAIL="+err.slice(-200)); process.exit(0);},1500);
  } else { if(err)console.log("STDERR_TAIL="+err.slice(-300)); process.exit(0);}
},1800);
'@
$tmp=Join-Path $env:TEMP "gwsim.mjs"; Set-Content $tmp $probe -Encoding utf8
& node $tmp 2>&1

